if canonical.exists():
 body=canonical.read_text();start='<!-- B9B11_PROGRESS:START -->';end='<!-- B9B11_PROGRESS:END -->';banner=start+'\n\n**B9–B11实施更新：** '+'；'.join(r['batch']+' '+str(r['samples_passed'])+'/'+str(r['samples_required'])+' 整例通过、'+str(r['samples_partial'])+' 部分完成' for r in rows)+'。详见 [实时表](https://github.com/zihaomu/CUDALibrarySamples_ROCm/blob/rocm/migration/reports/batches9-11.md)。完整支持与已验证子集分开统计。\n\n'+end+'\n\n'
 if start in body:body=body.split(start)[0]+banner+body.split(end,1)[1].lstrip('\n')
